<div class="row justify-content-center"><div class="col-lg-7"><div class="eyebrow">Join the archive</div><h1 class="fw-bold mt-2">Create an account</h1><form class="panel p-4 mt-4" method="post" action="<?= baseUrl('register') ?>" novalidate><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">First name</label><input class="form-control" name="first_name" pattern="[A-Za-z ]{2,50}" maxlength="50" required></div><div class="col-md-6"><label class="form-label">Last name</label><input class="form-control" name="last_name" pattern="[A-Za-z ]{2,50}" maxlength="50" required></div><div class="col-md-7"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="col-md-5"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="col-md-6"><label class="form-label">Location <span class="text-secondary">(optional)</span></label><input class="form-control" name="location" maxlength="100"></div><div class="col-md-6"><label class="form-label">Occupation <span class="text-secondary">(optional)</span></label><input class="form-control" name="occupation" maxlength="100"></div><div class="col-12"><label class="form-label">Short description <span class="text-secondary">(optional)</span></label><textarea class="form-control" name="description" rows="3"></textarea></div><div class="col-12"><button class="btn btn-dark">Create account</button></div></div></form></div></div>
